'use client';
import {useState} from 'react';
import {supabase} from '@/lib/supabase';
export default function Login(){const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [message,setMessage]=useState('');async function submit(e:React.FormEvent){e.preventDefault();if(!supabase){setMessage('Configure NEXT_PUBLIC_SUPABASE_URL e NEXT_PUBLIC_SUPABASE_ANON_KEY.');return}const {error}=await supabase.auth.signInWithPassword({email,password});setMessage(error?error.message:'Login efetuado com sucesso.');}return <main style={{minHeight:'100vh',display:'grid',placeItems:'center',background:'#101418',fontFamily:'Arial'}}><form style={{background:'#fff',borderRadius:16,width:'min(420px,92vw)',padding:34}} onSubmit={submit}><h1 style={{marginTop:0}}>ROYAL <span style={{color:'#d7a83f'}}>EPOXI</span></h1><p style={{color:'#6c737b'}}>Acesso à gestão da empresa</p><label>Email<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} style={{display:'block',width:'100%',padding:11,margin:'6px 0 15px'}} /></label><label>Password<input required type="password" value={password} onChange={e=>setPassword(e.target.value)} style={{display:'block',width:'100%',padding:11,margin:'6px 0 18px'}} /></label><button style={{width:'100%',padding:12,background:'#101418',color:'#fff',border:0,borderRadius:8}}>Entrar</button>{message&&<small style={{display:'block',marginTop:15,color:'#555'}}>{message}</small>}</form></main>}
